		translator.translate('[[user:chat-privacy]]', language),
		translator.translate('[[user:disable-incoming-messages]]', language),
		translator.translate('[[user:chat-allow-list]]', language),
		translator.translate('[[user:chat-deny-list]]', language),
		translator.translate('[[user:chat-list-help]]', language),
	]);
