				`<label class="form-label text-sm" for="chatDenyList">${denyLabel}</label>`,
				`<textarea class="form-control form-control-sm" id="chatDenyList" data-property="chatDenyList" rows="3">${denyList}</textarea>`,
			'</div>',
		].join('\n'),
	};
}

